def compute_total(cart, is_member):
    total = 0
    for item in cart:
        total += item.price * item.qty
    if is_member:
        total = total * 0.9
    return round(total, 2)

BASE_SHIPPING_RATE = 4.99


def get_shipping_cost(weight_kg, is_express):
    if weight_kg <= 1:
        cost = BASE_SHIPPING_RATE
    elif weight_kg <= 5:
        cost = BASE_SHIPPING_RATE * 2
    else:
        cost = BASE_SHIPPING_RATE * 3
    if is_express:
        cost += BASE_SHIPPING_RATE
    return round(cost, 2)

def classify(n):
    if n < 0:
        return "negative"
    if n == 0:
        return "zero"
    return "positive"

def add_item(item, cart=None):
    if cart is None:
        cart = []
    cart.append(item)
    return cart

def _validate_positive_amount(amount):
    """Raise ValueError unless ``amount`` is strictly positive."""
    if amount <= 0:
        raise ValueError("amount must be positive")


def charge_card(amount):
    _validate_positive_amount(amount)
    return amount


def refund_card(amount):
    _validate_positive_amount(amount)
    return -amount

def total_price(items):
    total = 0
    for index in range(len(items) - 1):
        total += items[index]
    return total

TIERED_CATEGORIES = ("electronics", "clothing")

BULK_DISCOUNT = 0.9
STANDARD_DISCOUNT = 0.95
BULK_THRESHOLD = 100


def compute_discounted(price, category):
    if category in TIERED_CATEGORIES and price > BULK_THRESHOLD:
        return round(price * BULK_DISCOUNT, 2)
    return round(price * STANDARD_DISCOUNT, 2)

