_VALID_PRIORITIES = frozenset(("low", "medium", "high"))


def parse_priority(value):
    """Normalize `value` to one of the allowed priority names.

    Raises ValueError when `value` is None or is not a recognized priority;
    never falls back to a default.
    """
    if value is None:
        raise ValueError("priority is required")
    normalized = str(value).strip().lower()
    if normalized not in _VALID_PRIORITIES:
        raise ValueError(f"invalid priority: {value}")
    return normalized

MINIMUM_ORDER_SUBTOTAL = 20
SERVICE_FEE_RATE = 0.05
INTERNATIONAL_SURCHARGE = 15.00
INTERNATIONAL_DISCOUNT = 2.00


def calculate_invoice_total(subtotal, is_international):
    if subtotal < MINIMUM_ORDER_SUBTOTAL:
        raise ValueError(f"subtotal below minimum of {MINIMUM_ORDER_SUBTOTAL}")
    total = subtotal + subtotal * SERVICE_FEE_RATE
    if is_international:
        total = total + INTERNATIONAL_SURCHARGE
        total = total - INTERNATIONAL_DISCOUNT
    return round(total, 2)
